1	//! Runs one package through a fresh real engine and returns its durable event
2	//! trail together with a DETERMINISTIC disposition.
3	//!
4	//! Two bindings make the run trustworthy:
5	//!
6	//! - Splice binding (r2 finding 1): the caller passes the EXACT entry-module
7	//!   bytes it expects the engine to load; `run_package` refuses to run unless
8	//!   the package's entry beam equals them, immediately before `load_workflows`.
9	//!   The reference run is bound to the reference entry bytes and the direct run
10	//!   to the `select()` bytes, so swapping `reference.clone()` in for the direct
11	//!   package fails before execution — the oracle can never compare a package to
12	//!   itself. `oracle_self_test.rs` exercises exactly that mis-binding.
13	//!
14	//! - Park evidence (r2 finding 3): a run is `Completed`/`Failed`/`Cancelled`
15	//!   the moment its terminal event is recorded, and `Parked` only on POSITIVE
16	//!   evidence — the engine's visibility surface reports the workflow `Running`
17	//!   (non-terminal) AND the history carries a specific `TimerStarted` with no
18	//!   matching `TimerFired`. A stability read is kept only as a supplementary
19	//!   guard. Bare signal waits expose no positive registration evidence through
20	//!   any engine surface, so signal-parking fixtures are excluded from the
21	//!   oracle upstream (see `covered.rs`), never inferred from silence.
22	
23	use std::collections::HashMap;
24	use std::sync::Arc;
25	use std::time::{Duration, Instant};
26	
27	use aion::EngineBuilder;
28	use aion_core::{Event, Payload, TimerId, WorkflowFilter, WorkflowId, WorkflowStatus};
29	use aion_package::Package;
30	use aion_store::{EventStore, InMemoryStore};
31	use serde_json::Value;
32	use uuid::Uuid;
33	
34	use crate::dispatcher::TypedDispatcher;
35	use crate::fixtures::ActionResult;
36	
37	/// Hard upper bound on a single run. No fixture that reaches a terminal or a
38	/// durable-timer park needs anywhere near this long; exceeding it is `Stuck`.
39	const RUN_DEADLINE: Duration = Duration::from_secs(15);
40	
41	/// History poll interval.
42	const POLL: Duration = Duration::from_millis(20);
43	
44	/// Supplementary stability guard: consecutive unchanged reads that must
45	/// accompany the positive park evidence before a park is accepted.
46	const STABLE_READS: u32 = 3;
47	
48	/// The recorded disposition of a run, derived entirely from durable history plus
49	/// the engine's visibility status.
50	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
51	pub enum Disposition {
52	    /// A terminal `WorkflowCompleted` was recorded.
53	    Completed,
54	    /// A terminal `WorkflowFailed` was recorded.
55	    Failed,
56	    /// A terminal `WorkflowCancelled` was recorded.
57	    Cancelled,
58	    /// Positive durable-timer park: visibility `Running`, a pending
59	    /// `TimerStarted`, no terminal event.
60	    Parked,
61	    /// Neither terminal nor positively parked within the deadline (infra).
62	    Stuck,
63	}
64	
65	/// The fixed workflow id both backends run under. Giving the reference and
66	/// direct runs the SAME identity is what "the same workflow, two byte
67	/// productions" means: a fixture that routes its own `workflow.id` into its
68	/// output then produces the identical result on both sides, controlling identity
69	/// at the experiment's inputs rather than in the normalizer (decision 11). Each
70	/// run uses a fresh in-memory store, so one shared id never collides.
71	pub fn shared_workflow_id() -> WorkflowId {
72	    WorkflowId::new(Uuid::from_u128(0x00bc_4d1f_0000_0000_0000_0000_0000_0001))
73	}
