75	/// The outcome of one run: its durable trail, disposition, and — as positive
76	/// park evidence — the pending durable timers observed at quiescence.
77	pub struct RunOutcome {
78	    /// The durable event trail (full when terminal, quiescent-partial when
79	    /// parked).
80	    pub trail: Vec<Event>,
