92	/// # Errors
93	///
94	/// Fails when the loaded package's entry beam does not match `expected_entry`,
95	/// or when the engine cannot be built/started or history cannot be read — every
96	/// such error is infrastructure, surfaced by the caller, never a disposition.
97	pub async fn run_package(
