137	            HashMap::new(),
138	            String::from("default"),
139	            Some(shared_workflow_id()),
140	            None,
141	        )
142	        .await?;
143	
144	    let deadline = Instant::now() + RUN_DEADLINE;
145	    let mut previous: Option<Vec<Event>> = None;
146	    let mut stable = 0u32;
147	    let outcome = loop {
148	        let history = store.read_history(handle.workflow_id()).await?;
149	        if let Some(disposition) = terminal_disposition(&history) {
150	            break outcome(history, disposition);
151	        }
152	        let pending = pending_timers(&history);
153	        stable = if previous.as_ref() == Some(&history) {
154	            stable + 1
155	        } else {
156	            0
157	        };
158	        // Positive park evidence: a specific pending timer AND visibility
159	        // reports the workflow Running, confirmed by a supplementary stable read.
160	        if !pending.is_empty()
161	            && stable >= STABLE_READS
162	            && is_running(&engine, workflow_type, handle.workflow_id()).await?
163	        {
164	            if std::env::var("BC4_PARK_PROBE").is_ok() {
165	                eprintln!(
